test('administrator placement layout reflows at 390px and a 200 percent equivalent viewport', async ({ page }) => {
  await setup(page);
  const pageDTO = { slug: 'home', title: 'Home', revision: `cr_${'a'.repeat(43)}`, items: [{ itemId: '222222222222222222222222', itemType: 'carousel', referenceId: '333333333333333333333333', order: 0, visibility: 'public', name: 'Featured releases and carefully selected recordings for late evenings', sourceMode: 'dynamic', referenceStatus: 'ready' }] };
  await page.route('**/api/admin/v1/pages/**', route => route.fulfill({ json: { page: pageDTO }, headers: { 'X-Finitude-Account-Viewer': viewer } }));
  await page.goto('/finitude/admin/pages'); await page.getByRole('button', { name: 'Switch to Admin view' }).click();
  // Halving a desktop layout viewport exercises the reflow used by 200 percent browser zoom.
  for (const width of [390, 640]) {
    await page.setViewportSize({ width, height: 844 });
    const title = page.getByRole('heading', { name: '1 · Featured releases and carefully selected recordings for late evenings' });
    await expect(title).toBeVisible();
    const bounds = await title.boundingBox(); expect(bounds!.x).toBeGreaterThanOrEqual(0); expect(bounds!.x + bounds!.width).toBeLessThanOrEqual(width);
    await page.getByRole('button', { name: 'Hide this placement' }).click();
    const dialog = page.getByRole('dialog', { name: 'Change visibility?' });
    await expect(dialog).toHaveAttribute('aria-describedby', /.+/);
    const target = await dialog.getByText('1 · Featured releases and carefully selected recordings for late evenings', { exact: true }).boundingBox();
    const cancel = dialog.getByRole('button', { name: 'Cancel', exact: true }), confirm = dialog.getByRole('button', { name: 'Hide this placement' });
    const cancelBounds = await cancel.boundingBox(), confirmBounds = await confirm.boundingBox();
    expect(target!.x).toBeGreaterThanOrEqual(0); expect(target!.x + target!.width).toBeLessThanOrEqual(width);
    expect(cancelBounds!.y).toBeGreaterThan(target!.y + target!.height); expect(confirmBounds!.x).toBeGreaterThanOrEqual(cancelBounds!.x + cancelBounds!.width);
    expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
    await page.keyboard.press('Escape'); await expect(dialog).toHaveCount(0); await expect(page.getByRole('button', { name: 'Hide this placement' })).toBeFocused();
  }
});

/** Echoes a created manifest and admits each queued upload; `hold` delays the first upload response. */
async function createRoutes(page: Page, hold?: Promise<void>) {
  const created: Array<Record<string, any>> = [], uploads: string[] = [], headers = { 'X-Finitude-Account-Viewer': viewer, 'Cache-Control': 'no-store' };
  let item = detail(), active = 0, max = 0;
  await page.route('**/api/admin/v1/imports**', async route => {
    const request = route.request(), path = new URL(request.url()).pathname;
    if (request.method() === 'POST' && path === '/api/admin/v1/imports') {
      const body = request.postDataJSON(); created.push(body);
      item = { ...detail(), manifest: body.manifest, suggestions: [], publication: 'notStarted', capabilities: { analysis: true, upload: true, publish: false }, upload: { ready: 0, total: body.manifest.files.length, available: true },
        draft: { album: detail().draft.album, tracks: body.manifest.files.map((file: { slotId: string }) => ({ slotId: file.slotId, title: '', trackNumber: null })) } };
      return route.fulfill({ status: 201, json: { item, receipt: { operationId: body.operationId, kind: 'create', revision: 1 } }, headers });
    }
    if (request.method() === 'POST' && path.includes('/assets/')) {
      active++; max = Math.max(max, active); uploads.push(path);
      if (uploads.length === 1) await hold;
      const slot = decodeURIComponent(path.split('/').at(-1)!), operationId = request.headers()['idempotency-key'];
      item = { ...item, revision: item.revision + 1, assets: [...item.assets, { slotId: slot, state: 'ready', ...uploadedFile(request), contentType: 'audio/mpeg', tags: null, recovery: { operationId, expectedRevision: Number(request.headers()['if-match']), kind: 'upload', startedByMe: true } }] };
      item.upload = { ...item.upload, ready: item.assets.length };
      active--; return route.fulfill({ json: { item, receipt: { operationId, kind: 'upload', revision: item.revision } }, headers });
    }
    if (path === '/api/admin/v1/imports') return route.fallback();
    return route.fulfill({ json: { item, receipt: null }, headers });
  });
  return { created, uploads, max: () => max };
}

test('one approval uploads files sequentially and leaving Admin view stops after the current file', async ({ page }, info) => {
  await setup(page); let release!: () => void; const hold = new Promise<void>(resolve => { release = resolve; }), server = await createRoutes(page, hold);
  const folder = info.outputPath('Synthetic Folder'); mkdirSync(folder, { recursive: true });
  for (const [index, name] of ['01 One.mp3', '02 Two.mp3', '03 Three.mp3'].entries()) writeFileSync(path.join(folder, name), Buffer.alloc(100 + index, index + 1));
  let dialogs = 0; page.on('dialog', () => { dialogs++; });
  await page.goto('/finitude/admin/imports/new'); await page.getByRole('button', { name: 'Switch to Admin view' }).click();
  await page.locator('input[type=file]').first().setInputFiles(folder);
  await expect(page.getByRole('textbox', { name: 'Folder or Album context' })).toHaveValue('Synthetic Folder');
  await page.getByRole('button', { name: 'Create import and upload files' }).click();
  await expect.poll(() => server.uploads.length).toBe(1);
  await page.getByRole('button', { name: 'Current view: Admin' }).click(); await page.getByRole('button', { name: 'User', exact: true }).click();
  await expect(page).toHaveURL(/\/finitude\/?$/);
  release(); await page.waitForTimeout(300); expect(server.uploads).toHaveLength(1);
  await page.goBack(); await page.getByRole('button', { name: 'Switch to Admin view' }).click();
  await page.getByRole('tab', { name: 'Files', exact: true }).click();
  await expect(page.getByText('1 of 3 files uploaded')).toBeVisible();
  await page.waitForTimeout(300); expect(server.uploads).toHaveLength(1);
  await page.getByRole('button', { name: 'Resume upload' }).click();
  await expect(page.getByText('3 of 3 files uploaded')).toBeVisible();
  expect(server.created).toHaveLength(1); expect(server.created[0].manifest.rootLabel).toBe('Synthetic Folder');
  expect(server.uploads.map(value => value.split('/').at(-1))).toEqual(server.created[0].manifest.files.map((file: { slotId: string }) => file.slotId));
  expect(server.max()).toBe(1); expect(dialogs).toBe(0); await expect(page.getByRole('dialog')).toHaveCount(0);
  await page.setViewportSize({ width: 390, height: 844 });
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
});

